      const a=z+.007,b=next-.007,shade=.62+.28*seeded(431+course*81+i);
      const x0=-1.14+1.28*(y0-tail)/(top-tail),x1=-1.14+1.28*(y1-tail)/(top-tail);
      quad(blocks,wp(a,x0,y0),wp(b,x0,y0),wp(b,x1,y1),wp(a,x1,y1),shade,.8);
      if(course===4)quad(cap,wp(a,x1,y1),wp(b,x1,y1),wp(b,1.36,y1),wp(a,1.36,y1),shade,.95);
